package ruins;

import hexxit.worldgen152.OldGameIds;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.fml.common.Mod;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.entity.player.PlayerEvent;
import ruins.gen.RuinsGen;

/**
 * Ruins 10.3 (AS_Ruins) for NeoForge: the ruins of the pack's templates, generated by {@link RuinsGen} in the 1.5.2
 * world of worldgen152. Like the original, hitting a block with a stick tells the block's name and state (at most
 * once a second), to help with writing templates.
 */
@Mod(Ruins.MOD_ID)
public final class Ruins {
    public static final String MOD_ID = "as_ruins";
    private long nextInfoTime;

    public Ruins(IEventBus modBus) {
        RuinsGen.register();
        // EnderCrystal of the templates (the original set bedrock under it)
        OldGameIds.registerEntity("EnderCrystal", "minecraft:end_crystal");
        NeoForge.EVENT_BUS.addListener(PlayerEvent.BreakSpeed.class, this::onBreakSpeed);
    }

    private void onBreakSpeed(PlayerEvent.BreakSpeed event) {
        if (event.getEntity().level().isClientSide() || !event.getEntity().getMainHandItem().is(Items.STICK)
                || System.currentTimeMillis() <= this.nextInfoTime) {
            return;
        }
        this.nextInfoTime = System.currentTimeMillis() + 1000L;
        BlockState state = event.getState();
        event.getEntity().sendSystemMessage(Component.literal(String.format("BlockName [%s], block [%s], state [%s]",
                state.getBlock().getName().getString(), BuiltInRegistries.BLOCK.getKey(state.getBlock()), state)));
    }
}
